function SignInPage() {
  return (
    <form>
      <label>
        Email <input type="email" name="email" />
      </label>
    </form>
  );
}

function RunReport({ collected }: { collected: number }) {
  return <PageShell title="Overnight run">Collected {formatMoney(collected)}</PageShell>;
}

function DirectorySignIn() {
  return <PageShell title="Sign in with the directory">Continue with the directory</PageShell>;
}

function table(name: string) {
  return {
    name,
    findMany: (_q?: unknown): any[] => [],
  };
}

function listOpenInvoices(): Invoice[] {
  return db.invoices.findMany({ where: { status: 'open' } });
}

function InvoiceList({ invoices = listOpenInvoices() }: { invoices?: Invoice[] }) {
  return (
    <ul>
      {invoices.map((inv) => (
        <li key={inv.id}>
          {inv.number} · due {format(inv.dueAt, 'd MMM yyyy')} · <AmountCell cents={inv.totalCents} />
        </li>
      ))}
    </ul>
  );
}

function AmountCell({ cents }: { cents: number }) {
  return <span style={{ textAlign: 'right' }}>{formatMoney(cents / 100)}</span>;
}

function PageShell({ title, children }: { title: string; children?: ReactNode }) {
  return (
    <main>
      <h1>{title}</h1>
      {children}
    </main>
  );
}

function formatMoney(amount: number, currency = 'USD'): string {
  return new Intl.NumberFormat('en-US', { style: 'currency', currency }).format(amount);
}
